    public void renderThumbnails(PreviewRow item) {
        List<ThumbnailData> thumbs = item.cachedThumbs;
        host.thumbnailPane().getChildren().clear();
        if (thumbs == null || thumbs.isEmpty()) {
            host.imageHintLabel().setText(Texts.get("preview.noImages"));
            host.imageHintLabel().setVisible(true);
            host.previewEffectButton().setVisible(false);
            host.imageScrollPane().setVisible(false);
            host.imageScrollPane().setManaged(false);
            return;
        }
        host.imageHintLabel().setVisible(false);
        host.previewEffectButton().setVisible(false);
        host.imageScrollPane().setVisible(true);
        host.imageScrollPane().setManaged(true);

        // 下标 = 缓存清单 meta.images() 的序号（cachedThumbs 与 meta 同序 1:1，见 openCachedImage 的索引语义）
        for (int i = 0; i < thumbs.size(); i++) {
            host.thumbnailPane().getChildren().add(buildThumbBox(item, thumbs.get(i), i));
        }
    }

    public void appendThumb(PreviewRow item, ThumbnailData entry, int index) {
        host.imageHintLabel().setVisible(false);
        host.previewEffectButton().setVisible(false);
        host.imageScrollPane().setVisible(true);
        host.imageScrollPane().setManaged(true);
        host.thumbnailPane().getChildren().add(buildThumbBox(item, entry, index));
    }

    public ThumbnailData decodeFile(com.mhtextractor.uiport.PortEvent.ImageFile file) {
        try {
            ThumbnailData decoded=decodeThumb(new PreviewImageData(file.coreName(),file.path(),
                    Files.readAllBytes(Path.of(file.path()))),file.index(),null);
            return new ThumbnailData(file.coreName(),decoded.width(),decoded.height(),decoded.pixels());
        } catch(java.io.IOException error) {
            return new ThumbnailData(file.coreName(),0,0,null);
        }
    }

    private VBox buildThumbBox(PreviewRow item, ThumbnailData entry, int index) {
        VBox box = new VBox(4);
        box.setAlignment(Pos.TOP_CENTER);
        // E1.4：模型只存像素；JavaFX Image 在此（渲染层）按需构造。构造失败等价于原 image == null
        Image fxImage = ThumbnailFxBridge.toFxImage(entry);
        if (fxImage == null) {
            box.getChildren().add(new Label(Texts.get("preview.loadFailed")));
        } else {
            ImageView iv = new ImageView(fxImage);
            iv.setFitWidth(150);
            iv.setFitHeight(150);
            iv.setPreserveRatio(true);
            box.getChildren().add(iv);
        }
        Label nameLabel = new Label(thumbFileName(entry, item));
        nameLabel.setWrapText(true);
        nameLabel.setMaxWidth(150);
        nameLabel.setStyle("-fx-font-size: 0.85em;");
        box.getChildren().add(nameLabel);
        // 点击查看（需求：预览区图片可点击查看）：单击缩略图 → 系统默认图片查看器打开缓存目录里对应的那张图
        box.setCursor(Cursor.HAND);
        Tooltip.install(box, new Tooltip(Texts.get("preview.thumbClickHint")));
        box.setOnMouseClicked(e -> { if (e.getButton() == MouseButton.PRIMARY) openCachedImage(item, index); });
        return box;
    }

    /** 单击缩略图：用系统默认图片查看器打开缓存目录里对应的图片（非 AWT；启动/校验/环境兜底见 {@link FileOpener}）。 */
    private void openCachedImage(PreviewRow item, int index) {
        // E1.2：cachedMeta 为 null（参数变更后清空 / 从未落盘）时安全返回，warn 复用既有
        // file == null 分支（同一日志键 log.maincontroller.65，不新增日志调用点）。
        Path file = item.cachedMeta == null || index >= item.cachedMeta.images().size() ? null
                : Path.of(item.cachedMeta.images().get(index).path());
        if (file == null || !Files.isRegularFile(file)) {
            log.warn(Texts.msg("log.maincontroller.65", item.name));
            return;
        }
        // index 语义见 renderThumbnails 注释；打开最多等 3 秒（校验退出码）再兜底 → 后台线程，避免冻结 FX 线程
        Thread t = new Thread(() -> {
            FileOpener.Route route = FileOpener.open(file);
            if (route == FileOpener.Route.FAILED) {
                log.warn(Texts.msg("log.maincontroller.65", item.name));
            } else {
                log.info(Texts.msg(route == FileOpener.Route.PHOTOS_PROTOCOL
                        ? "log.maincontroller.66" : "log.maincontroller.64", file));
            }
        }, "open-cached-image");
        t.setDaemon(true);
        t.start();
    }

    /** 合并输出且不重命名时，文件名按当前列表位置重算 f%02d_ 前缀（拖拽重排后同步刷新，按条目生效参数判定） */
    private String thumbFileName(ThumbnailData entry, PreviewRow item) {
        AppConfig params = host.effectiveParams(item);
        boolean mergedNoRename = params != null && params.isSingleOutputMode()
                && !params.isEnableBatchRenaming() && host.visibleCount() > 1;
        return mergedNoRename
                ? String.format("f%02d_", (int) host.unitIndex(item) + 1) + entry.coreName()
                : entry.coreName();
    }

    /**
     * 解码单张缩略图：WebP 走 JWebP 缩放解码（150 边界），其余走 JavaFX 原生缩放解码。
     *
     * <p>E1.4：返回值由"持有 JavaFX {@code Image}"改为"持有纯像素"（{@link ThumbnailData}），
     * 使该数据可脱离 UI 框架存在。解码仍在<b>后台线程</b>完成（缩放边界与算法不变），
     * JavaFX {@code Image} 的构造下沉到渲染层的
     * {@link com.mhtextractor.gui.util.ThumbnailFxBridge#toFxImage(ThumbnailData)}。失败时 pixels=null，
     * 渲染层显示"无法加载"占位 —— 与原 {@code image == null} 语义一致。</p>
     */
    public ThumbnailData decodeThumb(PreviewImageData imageData, int index, AppConfig params) {
        byte[] data = imageData.getData();
        String ext = PreviewNamingService.detectExtension(data, "jpg");
        boolean rename = params != null && params.isEnableBatchRenaming();
        String coreName = PreviewNamingService.imageFileName(imageData, ext, rename, index + 1, "");
        Image img = null;
        try {
            if ("webp".equals(ext)) {
                WebPImage webp = WebPImage.read(new ByteArrayInputStream(data),
                        WebPImageLoadOptions.builder()
                                .requestedWidth(150).requestedHeight(150)
                                .preserveRatio(true).smooth(true)
                                .build());
                img = new WebPFXImage(webp);
            } else {
                img = new Image(new ByteArrayInputStream(data), 150, 150, true, true);
            }
        } catch (Exception e) {
            // img 保持 null → 占位"无法加载"
        }
        return ThumbnailFxBridge.toThumbnailData(img, coreName);
    }
}
package com.mhtextractor.gui.controller;

import com.mhtextractor.app.SourceViewService;
import com.mhtextractor.app.Texts;
import com.mhtextractor.gui.component.GuiNotifications;
import com.mhtextractor.gui.component.HtmlSourceViewer;
import com.mhtextractor.uicore.PreviewRow;
import com.mhtextractor.platform.BrowserLauncher;
import javafx.application.Platform;
import javafx.scene.Node;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 源查看/浏览器动作协作者（C1a）—— 承载"在浏览器查看 HTML / 查看源码"这一组动作，
 * 从 {@code MainController} 原样外迁：浏览器查看页生成并发闸、导出、应用内源码查看器
 * 与系统浏览器启动都在本类；对宿主的全部能力需求收窄为 {@link Host} 两个方法。
 *
 * <p>搬迁前的成员在 {@code MainController} 上：{@code browserExporting} 字段、
 * {@code onContextOpenInBrowser} / {@code onContextViewSource}（右键菜单转发）与
 * {@code openHtmlInBrowser}（主体）。文案键、日志键、提醒图标/锚点、线程名
 * （{@code html-browser-export} / {@code html-browser-launch}）与 {@code browserExporting}
 * 的并发去重语义全部保持不变。</p>
 *
 * <p>本类含 JavaFX，属 {@code gui} 层；业务侧不得反向依赖它。</p>
 */
@Slf4j
public final class SourceViewActions {

    /** 宿主能力窄接口：本类不持有任何控件字段，只按这两个动作驱动界面。 */
    public interface Host {
        /** 提醒/查看器的锚点节点（搬迁前是 {@code refs.statusLabel()}）。 */
        Node anchor();

        /** 状态栏文案（搬迁前是 {@code refs.statusLabel().setText(...)}）。 */
        void setStatusText(String text);
    }

    private final Host host;

    /** 浏览器查看页生成并发闸（防重复点击并发导出） */
    private final AtomicBoolean browserExporting = new AtomicBoolean(false);

    public SourceViewActions(Host host) {
        this.host = host;
    }

    /** 在浏览器中查看（浏览器查看HTML需求）：导出 MHT 内嵌 HTML 后用系统默认浏览器打开渲染视图 */
    public void openInBrowser(Object target) {
        if (target instanceof PreviewRow it && !it.removed) {
            openHtmlInBrowser(it, false);
        }
    }

    /** 在浏览器中查看源码（浏览器查看HTML需求）：用 view-source: 打开导出页面的源码视图 */
    public void viewSource(Object target) {
        if (target instanceof PreviewRow it && !it.removed) {
            openHtmlInBrowser(it, true);
        }
    }

    /** 查看HTML源码按钮（浏览器查看HTML需求）：对列表当前选中条目打开源码视图 */
    public void viewSource(PreviewRow it) {
        openHtmlInBrowser(it, true);
    }

    /** 在系统默认浏览器中查看该 MHT 内嵌 HTML（sourceMode=true 走 view-source 源码视图） */
    private void openHtmlInBrowser(PreviewRow it, boolean sourceMode) {
        File f = new File(it.path);
        if (!f.exists()) {
            log.warn(Texts.msg("log.maincontroller.22", it.path));
            GuiNotifications.fileMissing(host.anchor(), it.path);
            return;
        }
        if (!browserExporting.compareAndSet(false, true)) {
            log.info(Texts.msg("log.maincontroller.23"));
            return;
        }
        host.setStatusText(Texts.get("browser.generatingPage"));
        Thread t = new Thread(() -> {
            try {
                SourceViewService.Export result = SourceViewService.export(it.path);
                switch (result) {
                    case SourceViewService.Export.Unparseable() ->
                            throw new IllegalStateException(Texts.get("browser.exportUnparseable"));
                    case SourceViewService.Export.Failed(String detailKey, java.util.Map<String, String> detailParams) ->
                            throw new IllegalStateException(WorkspaceInfoPresenter.detailText(detailKey, detailParams));
                    case SourceViewService.Export.Success(Path htmlFile, int imageCount, int warningCount) -> {
                        log.info(Texts.msg("log.maincontroller.24", htmlFile, imageCount, warningCount));
                        // 浏览器启动可能耗时（注册表探测 / CDP 端点等待最长约 15 秒），独立后台线程避免冻结界面
                        Thread launcher = new Thread(() -> {
                            if (sourceMode) {
                                // R2：源码不再交给外部浏览器，改为应用内左侧覆盖式查看器（禁用 WebView，R2.6）。
                                HtmlSourceViewer.showFile(host.anchor(), Texts.get("browser.viewerTitle"), htmlFile);
                                return;
                            }
                            boolean ok = BrowserLauncher.openHtml(htmlFile);
                            if (!ok) {
                                log.warn(Texts.msg("log.maincontroller.25", htmlFile));
                                Platform.runLater(() -> GuiNotifications.browserLaunchFailed(host.anchor(), htmlFile));
                            }
                        }, "html-browser-launch");
                        launcher.setDaemon(true);
                        launcher.start();
                    }
                }
            } catch (Exception e) {
                log.error(Texts.msg("log.maincontroller.26", it.path), e);
                Platform.runLater(() -> GuiNotifications.browserViewFailed(host.anchor()));
            } finally {
                browserExporting.set(false);
                Platform.runLater(() -> host.setStatusText(Texts.get("main.statusReady")));
            }
        }, "html-browser-export");
        t.setDaemon(true);
        t.start();
    }
}

